pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    HelperReceiver hr;

    function setUp() public { 
        c = new C();
        hr = new HelperReceiver();
    }

    // fuzz params: from address and an array of target addresses and a value
    function testFuzz_property(address from, address to1, uint256 v) public {
        // Keep addresses non-zero to be realistic
        vm.assume(from != address(0));
        vm.assume(to1 != address(0));

        // Build a small array of one address (fuzzer supplies to1)
        address[] memory tos = new address[](1);
        tos[0] = address(hr); // route external call through helper which returns true

        // The helper will accept the encoded selector and return successfully.
        // We call transfer and capture whether it returned true (without revert) via try/catch
        bool ok;
        try c.transfer(from, address(hr), tos, v) returns (bool ret) {
            // expect reference to return true for all non-reverting calls
            ok = ret;
        } catch {
            // If it reverts, rule is about non-reverting calls, so treat as not-applicable; set ok = true
            // to avoid failing the assertion for reverting cases
            ok = true;
        }

        // The single assertion: for the reference implementation this is always true; the mutant that
        // returns false on success will cause this assertion to fail for some inputs the fuzzer finds.
        assertTrue(ok);
    }
}

// Minimal helper that accepts the call and returns true (does not revert).
contract HelperReceiver {
    // Accept any calldata and return true (as a single bool) encoded
    fallback() external payable returns (bytes memory) {
        // emulate successful execution of transferFrom by returning nothing (call() in C only requires success boolean)
        // Returning no data is acceptable; low-level call returns success=true.
        return "";
    }
}

