pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the from address, an arbitrary uint value, and an array of recipient addresses
    function testFuzz_property(address from, uint256 v, address[] memory tos) public {
        // admissible domain: tos must be non-empty per C.transfer's require
        vm.assume(tos.length > 0);
        // Ensure recipient addresses are contracts that will accept the low-level call.
        // The reference C expects the called contract to respond true for transferFrom; we provide
        // a benign callee that returns true to the selector. Deploy one helper and use its address
        // for all targets in the tos array to keep the scenario simple and within fuzzer control.
        ReceiverGood r = new ReceiverGood();

        address caddr = address(r);

        // build a targets array filled with the helper contract address
        address[] memory targets = new address[](tos.length);
        for (uint i = 0; i < tos.length; i++) {
            targets[i] = caddr;
        }

        // call transfer and capture whether it completes (it should) and its return using try/catch
        bool ok;
        try c.transfer(from, caddr, targets, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false; // if it reverts, mark as false (not expected for admissible inputs with our helper)
        }

        // The universal property: for all admissible inputs (tos.length>0 and callee responds successfully),
        // the correct C returns true (so ok == true). The mutant that returns false will break this for some inputs.
        assertTrue(ok);
    }
}

// Minimal benign callee that responds true to selector transferFrom(address,address,uint256)
contract ReceiverGood {
    // match selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    // using low-level fallback to decode selector and return true
    fallback() external payable returns (bytes memory) {
        // simply return abi.encode(true) for any call matching expected selector
        return abi.encode(true);
    }
}

