pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: from, calleeWillSucceed (as a boolean encoded in uint8), tosLength
    function testFuzz_property(address from, uint8 calleeSucceeds, uint8 tosLen) public {
        // keep tosLen small but allow zero to be excluded by assume
        uint8 boundedLen = uint8(bound(tosLen, 1, 5));
        vm.assume(from != address(0));

        // build tos array of length boundedLen filled with a helper contract that will mimic an ERC20-like transferFrom
        address helper = address(new CalleeSuccess());
        address helperFail = address(new CalleeRevert());
        address chosen = (calleeSucceeds % 2 == 0) ? helper : helperFail;

        address[] memory tos = new address[](boundedLen);
        for (uint i = 0; i < boundedLen; i++) tos[i] = chosen;

        // Call transfer and capture whether it completes (does not revert) and the returned bool when possible
        bool ok;
        bool ret;
        try c.transfer(from, chosen, tos, 1) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // The universal property: when the call completes (ok == true), the correct contract always returns true.
        // The mutant returns false on successful completion, so the assertion below will fail for the mutant
        // for inputs where the callee succeeds (i.e., helper used) and thus ok == true but ret == false.
        assertTrue(!ok || ret);
    }
}

// Helper that simulates a callee whose low-level call succeeds (returns true)
contract CalleeSuccess {
    // match any calldata and return true (non-empty return data is okay)
    fallback() external payable returns (bytes memory) {
        // return 32-byte true (non-zero) so the caller's require(_s) sees true
        bytes memory ret = abi.encode(true);
        return ret;
    }
}

// Helper that reverts on any call
contract CalleeRevert {
    fallback() external payable {
        revert("fail");
    }
}

