pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // helper that forwards the expected transferFrom signature and returns successfully
    contract GoodCallee {
        event Called(address from, address to, uint256 v);
        // mimic transferFrom(address,address,uint256)
        function transferFrom(address from, address to, uint256 v) external returns (bool) {
            emit Called(from, to, v);
            return true;
        }
    }

    function setUp() public { c = new C(); }

    // Fuzz parameters: an arbitrary from address, an arbitrary uint v, and an array of recipient addresses
    function testFuzz_property(address from, uint256 v, address[] memory tos) public {
        // Keep domain wide but ensure tos is non-empty (function requires it)
        vm.assume(tos.length > 0);

        // Deploy a helper callee that will accept the low-level call and return success
        GoodCallee callee = new GoodCallee();

        // Call transfer on c and observe whether it completes (does not revert) using try/catch.
        // According to the correct contract, when it completes it should return true. We capture completion and returned value.
        bool completed;
        bool ret;
        try c.transfer(from, address(callee), tos, v) returns (bool r) {
            completed = true;
            ret = r;
        } catch {
            completed = false;
            ret = false;
        }

        // The universal property we assert: if the call completed then the returned value must be true.
        // The reference C satisfies this for all inputs; the mutant (which returns false on success) will fail this assertion for some inputs.
        if (completed) {
            assertTrue(ret);
        } else {
            // If it reverted, we cannot assert about return value; just assert true to keep single assertion conditional structure.
            // But to follow the rule of exactly one assertTrue reading c, we assert on a pure observation: completed implies ret via the above.
            assertTrue(true);
        }
    }
}

